import React from 'react';
import ProfileCard from './components/ProfileCard';
function App() {
  // Array ข้อมูลสมาชิก 3 คน ตามโจทย์
  const members = [
    {
      id: 1,
      name: 'สมชาย สายลุย',
      nickname: 'ชาย',
      major: 'วิทยาการคอมพิวเตอร์',
      favorites: ['เขียนโค้ด', 'เล่นเกม FPS', 'ดื่มกาแฟ']
    },
    {
      id: 2,
      name: 'สมหญิง รักดี',
      nickname: 'หญิง',
      major: 'เทคโนโลยีสารสนเทศ',
      favorites: ['วาดรูป', 'ฟังเพลง', 'เที่ยวคาเฟ่']
    },
    {
      id: 3,
      name: 'กิตติศักดิ์ มีสุข',
      nickname: 'กิต',
      // ไม่ระบุ major เพื่อทดสอบ Default Prop 'ยังไม่ระบุสาขา'
      favorites: ['ดูหนัง', 'ออกกำลังกาย']
    }
  ];

  return (
    <div className="app-container">
      <h1 className="app-title">สมาชิกกลุ่มของเรา</h1>

      {/* Container แบบ Flexbox */}
      <div className="card-grid">
        {members.map((m) => (
          <ProfileCard
            key={m.id}
            name={m.name}
            nickname={m.nickname}
            major={m.major}
            favorites={m.favorites}
          />
        ))}
      </div>
    </div>
  );
}

export default App;
